import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
INF = 10**9
dist = [[INF] * n for _ in range(n)]
for i in range(n):
    dist[i][i] = 0
for i in range(m):
    a = int(data[2 + 2 * i])
    b = int(data[3 + 2 * i])
    dist[a][b] = dist[b][a] = 1
for k in range(n):
    for i in range(n):
        for j in range(n):
            if dist[i][k] + dist[k][j] < dist[i][j]:
                dist[i][j] = dist[i][k] + dist[k][j]
dp = [[INF] * n for _ in range(1 << n)]
for v in range(n):
    dp[1 << v][v] = 0
for mask in range(1, 1 << n):
    for v in range(n):
        cur = dp[mask][v]
        if cur >= INF:
            continue
        for w in range(n):
            if not mask >> w & 1:
                nm = mask | (1 << w)
                if cur + dist[v][w] < dp[nm][w]:
                    dp[nm][w] = cur + dist[v][w]
print(min(dp[(1 << n) - 1]))

